<?php
function admin_page_start($title,$subtitle='',$map=false){require_role('admin');layout_start($title,$subtitle,$map);echo '<div class="admin-workspace">';}
function admin_page_end(){echo '</div>';layout_end();}
function admin_pager($page,$pages,$total){if(!$total || $pages<2)return;?><nav class="pagination" aria-label="Pages"><span>Page <?=$page?> of <?=$pages?></span><?php foreach([-1=>'← Previous',1=>'Next →'] as $d=>$label):if($page+$d<1||$page+$d>$pages)continue;$query=$_GET;$query['p']=$page+$d;?><a href="?<?=e(http_build_query($query))?>"><?=$label?></a><?php endforeach;?></nav><?php }
function admin_assignment_queues(){return [
 'review'=>['Needs review',"i.status='Submitted'"],
 'ready'=>['Ready to assign',"i.status='Verified' AND i.officer_id IS NULL"],
 'confirmation'=>['Assignments to verify',"i.status='Verified' AND i.officer_id IS NOT NULL"],
 'assigned'=>['Assigned / reassign',"i.officer_id IS NOT NULL AND i.status IN ('Assigned','In Progress')"],
 'unassigned'=>['All unassigned',"i.officer_id IS NULL AND i.status IN ('Submitted','Verified')"]
];}
function admin_assignment_counts(){$parts=[];foreach(admin_assignment_queues() as $k=>$v)$parts[]='COALESCE(SUM('.$v[1].'),0) `'.$k.'`';return q('SELECT '.implode(',',$parts).' FROM issues i WHERE i.duplicate_of IS NULL')->fetch();}
function admin_tabs($page,$items,$selected){?><nav class="admin-tabs" aria-label="Workspace tabs"><?php foreach($items as $key=>$label):?><a class="<?=$key===$selected?'selected':''?>" href="?<?=e(http_build_query(['page'=>$page,'tab'=>$key]))?>" <?=$key===$selected?'aria-current="page"':''?>><?=e($label)?></a><?php endforeach;?></nav><?php }
function admin_action_label($action){$labels=['issue.created'=>'Report submitted','issue.updated'=>'Report updated','issue.assigned'=>'Officer assignment saved','issue.resolution_approved'=>'Resolution approved','issue.team_assign'=>'Maintenance team assigned','issue.team_review'=>'Team completion reviewed','issue.team_start'=>'Team started work','issue.team_submit'=>'Team completion submitted','issue.team_progress'=>'Team progress uploaded','user.created'=>'Account created','user.activation'=>'Account access changed','user.updated'=>'Account name updated','officer.coverage'=>'Officer coverage updated','routing.account_created'=>'Scoped account created','routing.account_mapped'=>'Account responsibility updated','issue.routed'=>'Report routing updated','town.created'=>'Town created','category.created'=>'Category created','category.renamed'=>'Category renamed','category.activation'=>'Category availability changed','area.created'=>'Service area created','system.backup_restored'=>'Backup restored','issue.reviewed'=>'Report reviewed'];return $labels[$action]??ucwords(str_replace(['.','_'],' ',$action));}
function admin_csv_cell($v){return preg_match('/^[\x00-\x20]*[=+@\-]/',(string)$v)?"'".$v:$v;}
function admin_audit_filter(){
 require_role('admin');$w=['1=1'];$p=[];$f=['from'=>valid_date(trim((string)($_GET['from']??'')),'from'),'to'=>valid_date(trim((string)($_GET['to']??'')),'to'),'actor'=>max(0,(int)($_GET['actor']??0)),'action'=>(string)($_GET['event']??''),'issue'=>max(0,(int)($_GET['issue']??0))];
 if($f['from']&&$f['to']&&$f['from']>$f['to'])throw new RuntimeException('The start date must be on or before the end date.');
 if($f['from']){$w[]='a.created_at>=?';$p[]=$f['from'].' 00:00:00';}if($f['to']){$w[]='a.created_at<DATE_ADD(?,INTERVAL 1 DAY)';$p[]=$f['to'];}if($f['actor']){$w[]='a.actor_id=?';$p[]=$f['actor'];}if($f['action']!==''){$w[]='a.action=?';$p[]=$f['action'];}if($f['issue']){$w[]="a.action LIKE 'issue.%' AND (a.details REGEXP ? OR (a.action='issue.merged' AND a.details REGEXP ?) OR a.details LIKE ?)";$p[]='^(Issue|Report) #'.$f['issue'].'([^0-9]|$)';$p[]='(^#'.$f['issue'].' → #[0-9]+$|^#[0-9]+ → #'.$f['issue'].'$)';$p[]='%"target":"Issue #'.$f['issue'].'"%';}
 return ['sql'=>' WHERE '.implode(' AND ',$w),'params'=>$p,'values'=>$f];
}
function admin_audit_export(){
 $f=admin_audit_filter();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="civiccare-audit.csv"');$out=fopen('php://output','w');fputcsv($out,['When','Actor','Action','Action code','Details']);$rows=q('SELECT a.*,u.name FROM audit_log a LEFT JOIN users u ON u.id=a.actor_id'.$f['sql'].' ORDER BY a.id DESC',$f['params']);while($r=$rows->fetch())fputcsv($out,array_map('admin_csv_cell',[$r['created_at'],$r['name'],admin_action_label($r['action']),$r['action'],$r['details']]));fclose($out);
}
function admin_report_filters($filter){$f=$filter['values'];?><form method="get" class="panel staff-filters admin-report-filters"><input type="hidden" name="page" value="reports"><div class="admin-filter-grid"><label>Search reports<input name="search" maxlength="160" value="<?=e($f['search']??'')?>" placeholder="Title, location or #ID"></label><?php foreach(['category'=>'Category','status'=>'Status','priority'=>'Priority'] as $key=>$label):?><label><?=$label?><select name="<?=$key?>"><option value="">All <?=(['category'=>'categories','status'=>'statuses','priority'=>'priorities'][$key])?></option><?php $options=$key==='category'?array_column(categories(),'name','id'):array_combine($key==='status'?staff_statuses():['High','Medium','Low'],$key==='status'?staff_statuses():['High','Medium','Low']);foreach($options as $v=>$name):?><option value="<?=e($v)?>" <?=(string)$f[$key]===(string)$v?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></label><?php endforeach;?></div><details class="admin-advanced" <?=count(array_intersect(array_keys($_GET),['from','to','area','officer','team','team_stage','view','sort']))?'open':''?>><summary>Advanced filters · dates, officer and team</summary><div class="admin-filter-grid"><?php foreach(['from'=>'Reported from','to'=>'Reported to'] as $k=>$label):?><label><?=$label?><input type="date" name="<?=$k?>" value="<?=e($f[$k])?>"></label><?php endforeach;foreach(['officer'=>['Officer',array_column(q("SELECT id,name FROM users WHERE role='officer' ORDER BY name")->fetchAll(),'name','id')],'team'=>['Maintenance team',array_column(q("SELECT id,name FROM users WHERE role='maintenance' ORDER BY name")->fetchAll(),'name','id')],'team_stage'=>['Team stage',['none'=>'No team assigned','Assigned'=>'Assigned to team','In Progress'=>'Team working','Returned'=>'Returned to team','Review'=>'Officer review needed','Approved'=>'Officer approved']],'view'=>['Work queue',['all'=>'All work','unassigned'=>'Unassigned','overdue'=>'Overdue','high'=>'High priority','approval'=>'Province final approval']],'sort'=>['Sort by',['priority'=>'Priority, oldest first','due'=>'Due date','oldest'=>'Oldest first','newest'=>'Newest first']]] as $key=>$info):?><label><?=$info[0]?><select name="<?=$key?>"><?php if(!in_array($key,['view','sort'],true)):?><option value="">All</option><?php endif;foreach($info[1] as $v=>$name):?><option value="<?=e($v)?>" <?=(string)$f[$key]===(string)$v?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></label><?php endforeach;?></div></details><?php geo_filter_controls($f);?><div class="row"><button class="button secondary">Apply filters</button><a class="text-link" href="index.php?page=reports">Reset</a><span class="small muted">CSV matches this selection. Dates refer to report submission.</span></div></form><?php }
function admin_upload_limits(){global $config;$u=ops_bytes(ini_get('upload_max_filesize'));$p=ops_bytes(ini_get('post_max_size'));$available=$p?max(0,$p-65536):PHP_INT_MAX;return ['photo'=>min((int)$config['upload_max_bytes'],$u?:PHP_INT_MAX,$available),'restore'=>min((int)ops_options()['backup_max_bytes'],$u?:PHP_INT_MAX,$available),'post'=>$p,'upload'=>$u];}
function admin_size($n){return number_format($n/1048576,1).' MB';}
function admin_report_table($rows){
 if(!$rows){echo '<div class="admin-empty"><h3>No matching reports</h3><p>Try another filter or reset the selection.</p></div>';return;}
?><div class="table-wrap admin-reports-table"><table><thead><tr><th>Report / Province / District / Town</th><th>Priority</th><th>Status</th><th>Officer</th><th>Maintenance team</th><th>Team stage</th><th>Due / attention date</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $i):$legacy=$i['status']==='Verified'&&$i['officer_id'];$url=$legacy?'index.php?page=assignments&view=confirmation&id='.$i['id'].'#assignment':'index.php?page=issue&id='.$i['id'];?><tr><td data-label="Report"><a class="table-title" href="index.php?page=issue&amp;id=<?=$i['id']?>">#<?=$i['id']?> · <?=e($i['title'])?></a><small class="muted"><?=e(($i['province_name']?:'Not classified').' / '.($i['district_name']?:'Not classified').' / '.($i['town_name']?:'Not classified'))?><br><?=e($i['category'])?></small></td><td data-label="Priority"><span class="priority-chip p-<?=strtolower($i['priority'])?>"><?=e($i['priority'])?></span></td><td data-label="Status"><?=badge($i['status'])?><?php if($legacy):?><small class="muted">Assignment to verify</small><?php endif;?></td><td data-label="Officer"><?=e($i['officer']?:'Unassigned')?></td><td data-label="Team"><?=e($i['maintenance_team']?:'Not assigned')?></td><td data-label="Team stage"><?=e($i['maintenance_stage']==='Review'?'Officer review needed':($i['maintenance_stage']?:'—'))?></td><td data-label="Due date"><?=e($i['due_date']?:date('Y-m-d',strtotime($i['created_at'].' +7 days')))?><?php if(!$i['due_date']):?><small class="muted">7-day attention date</small><?php endif;?></td><td data-label="Action"><a class="button secondary" href="<?=e($url)?>"><?=$legacy?'Confirm':'View'?> →</a></td></tr><?php endforeach;?></tbody></table></div><?php
}

function admin_audit_issue_ids($action,$details){
 $change=json_decode($details,true);if(is_array($change)&&($change['format']??'')==='civic-change-1'&&strpos($action,'issue.')===0&&preg_match('/^Issue #([1-9][0-9]*)$/',(string)($change['target']??''),$m))return [(int)$m[1]];
 if(strpos($action,'issue.')!==0)return [];
 if($action==='issue.merged'&&preg_match('/^#([1-9][0-9]*) → #([1-9][0-9]*)$/u',$details,$m))return array_values(array_unique([(int)$m[1],(int)$m[2]]));
 if(preg_match('/^(?:Issue|Report) #([1-9][0-9]*)(?:[^0-9]|$)/',$details,$m))return [(int)$m[1]];
 return [];
}
function admin_account_scope($u){
 $id=(int)$u['id'];
 if($u['role']==='admin'&&!empty($u['is_system_admin']))return 'System Admin';
 if($u['role']==='admin'){$names=geo_raw('SELECT name FROM geo_provinces WHERE admin_id=?',[$id])->fetchAll();return 'Province Admin — '.($names?implode(', ',array_column($names,'name')):'Not configured');}
 if($u['role']==='officer'){$names=geo_raw('SELECT CONCAT(p.name,\' / \',d.name) name FROM geo_districts d JOIN geo_provinces p ON p.id=d.province_id WHERE d.officer_id=?',[$id])->fetchAll();return 'District Officer — '.($names?implode(', ',array_column($names,'name')):'Not configured');}
 if($u['role']==='maintenance'){$name=geo_raw('SELECT CONCAT(p.name,\' / \',d.name,\' / \',t.name) FROM geo_towns t JOIN geo_districts d ON d.id=t.district_id JOIN geo_provinces p ON p.id=d.province_id WHERE t.id=?',[(int)($u['town_id']??0)])->fetchColumn();return 'Maintenance Team — '.($name?:'Town not configured');}
 return 'Citizen';
}

function admin_audit_details($action,$details){
 $change=json_decode($details,true);if(is_array($change)&&($change['format']??'')==='civic-change-1')return (string)($change['target']??'Responsibility').' — '.(string)($change['reason']??'');
 if($action==='issue.assigned'&&preg_match('/^Issue #([1-9][0-9]*) officer #([1-9][0-9]*)$/',$details,$m)){
  $name=q('SELECT name FROM users WHERE id=?',[(int)$m[2]])->fetchColumn();
  return 'Report #'.$m[1].' assigned to '.($name?:'Unavailable officer').' (officer #'.$m[2].').';
 }
 return $details;
}
